pilha = []
for simbolo in "9 3 - 8 2 / -".split():
    if simbolo.isdigit():
        pilha.append(int(simbolo))
    else:
        direito = pilha.pop()
        esquerdo = pilha.pop()
        if simbolo == "-":
            pilha.append(esquerdo - direito)
        else:
            pilha.append(esquerdo // direito)
print(pilha.pop())

