pares = {")": "(", "]": "[", "}": "{"}
pilha = []
posicao = -1
for i, simbolo in enumerate("{[()]}([)]"):
    if simbolo in "([{":
        pilha.append(simbolo)
    elif not pilha or pilha.pop() != pares[simbolo]:
        posicao = i
        break
print(posicao, len(pilha))

